"""Internal connector CES replay; never registered for arbitrary uploaded files."""
from __future__ import annotations

import hashlib
import json
from copy import deepcopy
from pathlib import Path

from saw.parsers.structured import JsonLinesParser

# Only source facts enter the CES envelope. Identity, ownership, raw paths, parser
# provenance and observations are always regenerated by the local producer.
_CONNECTOR_FIELDS = frozenset(["timestamp", "timestamp_raw", "timestamp_tz", "timestamp_quality", "data_source", "product", "event_type", "severity", "src_ip", "src_port", "dst_ip", "dst_port", "protocol", "hostname", "user", "session_id", "request_id", "method", "uri", "status_code", "bytes_in", "bytes_out", "user_agent", "domain", "process", "hash", "ja3", "ja4", "community_id", "duration", "action", "outcome", "enforcement_action", "tags"])
_RESERVED_EXT = frozenset(["observation", "saw_observation", "device_observation", "connector", "context", "source_context", "provenance", "producer", "owner", "raw_ref", "generation", "org_unit", "org_unit_id", "source", "source_id"])


def connector_facts(upstream):
    facts = {key: deepcopy(value) for key, value in upstream.items() if key in _CONNECTOR_FIELDS}
    extension = upstream.get('ext')
    if isinstance(extension, dict):
        facts['ext'] = {key: deepcopy(value) for key, value in extension.items()
                        if key not in _RESERVED_EXT and not key.startswith(('saw_', '_'))}
    return facts


class ConnectorEnvelopeParser(JsonLinesParser):
    """Replay server-prepared CES facts while to_ces supplies local provenance."""
    def parse_line(self, line):
        from saw.parsers.base import Failed, Parsed
        try:
            envelope = json.loads(line)
        except (ValueError, TypeError):
            return Failed('invalid connector envelope')
        if not isinstance(envelope, dict):
            return Failed('invalid connector envelope')
        facts = envelope.get('event') if envelope.get('format') == 'saw-connector-ces/1' else envelope
        if not isinstance(facts, dict):
            return Failed('invalid connector event')
        fields = connector_facts(facts)
        fields.setdefault('ext', {})['connector'] = {
            'id': envelope.get('connector_id'), 'source_event_id': envelope.get('connector_source_event_id')}
        if fields.get('timestamp') and not fields.get('timestamp_raw'):
            fields['timestamp_raw'] = fields['timestamp']
        return Parsed(fields)



def connector_implementation_pin():
    """Fresh fingerprint of the concrete implementation and its field policy."""
    try:
        digest = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    except OSError:
        digest = ''
    return {'implementation': 'saw.parsers.connector.ConnectorEnvelopeParser',
            'version': str(ConnectorEnvelopeParser.version), 'digest': digest}
